function SelectionListWithModal<TItem extends ListItem>(props: SelectionListWithModalProps<TItem>) {
    const {initiallyFocusedOptionKey, onSelectRow, onDismissError, onLongPressRow, shouldStopPropagation, shouldPreventDefault, shouldUseDynamicMaxToRenderPerBatch, isRowMultilineSupported, ...rest} =
        props;
    const {isSmallScreenWidth} = useResponsiveLayout();

    const onSelectRowHandler = (item: TItem) => {
        if (isSmallScreenWidth && onSelectRow) {
            Navigation.goBack();
        }
        onSelectRow?.(item);
    };

    return (
        <BaseSelectionList
            // eslint-disable-next-line react/jsx-props-no-spreading
            {...rest}
            initiallyFocusedOptionKey={initiallyFocusedOptionKey}
            onSelectRow={onSelectRowHandler}
            onDismissError={onDismissError}
            onLongPressRow={onLongPressRow}
            shouldStopPropagation={shouldStopPropagation}
            shouldPreventDefault={shouldPreventDefault}
            shouldUseDynamicMaxToRenderPerBatch={shouldUseDynamicMaxToRenderPerBatch}
            isRowMultilineSupported={isRowMultilineSupported}
        />
    );
}

