function SelectionListWithModal<TItem extends ListItem>(props: SelectionListWithModalProps<TItem>) {
    const {
        initiallyFocusedOptionKey,
        onSelectRow,
        onDismissError,
        onLongPressRow,
        shouldStopPropagation,
        shouldPreventDefault,
        shouldUseDynamicMaxToRenderPerBatch,
        isRowMultilineSupported,
        isFromGroupedReport,
        ...rest
