function BaseListItem<TItem extends ListItem>({
    item,
    isFocused = false,
    isDisabled = false,
    showTooltip,
    canSelectMultiple = false,
    onSelectRow,
    onCheckboxPress,
    onDismissError,
    onFocus,
    onLongPressRow,
    pressableStyle,
    wrapperStyle,
    containerStyle,
    shouldSyncFocus,
    hoverStyle,
    isFromGroupedReport,
}: BaseListItemProps<TItem>) {
    const styles = useThemeStyles();
    const StyleUtils = useStyleUtils();
    const {shouldUseNarrowLayout} = useResponsiveLayout();
    const {translate} = useLocalize();
    const {selectionMode} = useMobileSelectionMode();
    const [isHovered, setIsHovered] = useState(false);

    const isDeleted = !!item.pendingAction && item.pendingAction === CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE;
    const isComponentFocused = !isDeleted && isFocused;
    const isMultipleSelection = canSelectMultiple && !!selectionMode?.isEnabled;
    const canSelect = !!onSelectRow || !!onCheckboxPress;
    const isItemSelectable = canSelect && !isDeleted && !isDisabled;
    const isItemActuallySelected = !!item.isSelected && !isDeleted;

    const handleFocus = useCallback(() => {
        onFocus?.(item);
    }, [item, onFocus]);

